impl Solution {
    pub fn count_monobit(n: i32) -> i32 {
        if n < 0 {
            return 0;
        }
        let mut count = 0;
        for i in 0..=n {
            let mut num = i;
            let mut first_bit = -1;
            let mut all_same = true;
            while num > 0 {
                let bit = num & 1;
                if first_bit == -1 {
                    first_bit = bit;
                } else if bit != first_bit {
                    all_same = false;
                    break;
                }
                num >>= 1;
            }
            if all_same || i == 0 {
                count += 1;
            }
        }
        count
    }
}

